//! The two match tables, generated by `build.rs`.
//!
//! - [`NATIVE`]: from the `hwbus.ids` file each native driver crate carries
//!   beside its `Cargo.toml`, one line per id (`<driver> <selector>
//!   [boot] [if=<KCONFIG_SYMBOL>]`). A line whose Kconfig symbol is off is left
//!   out, so a driver the image does not compile has no entry and its
//!   devices are not claimed on its behalf.
//! - [`LINUX`]: from `tools/lx_device_table.py`, which reads the
//!   `MODULE_DEVICE_TABLE` of the Linux leaf drivers listed in
//!   `lx/DEVICE_SOURCES` out of the pinned Linux checkout. Empty while that tree
//!   or that list is.
//!
//! `build.rs` refuses a build in which a native pattern and a Linux pattern
//! overlap ([`crate::pattern::Pattern::overlaps`]): one id, one owner.

use crate::pattern::Pattern;

/// One native id: the in-kernel driver `driver` answers to `pattern`.
#[derive(Clone, Copy, Debug)]
pub struct NativeEntry {
    pub pattern: Pattern<'static>,
    pub driver: &'static str,
    /// The kernel needs this hardware to boot (console, interrupt controller,
    /// PCI host) and brought it up before the bus existed: the device is
    /// bound to its driver whatever the policy and the topology say. A
    /// device the kernel is already driving must never read as unclaimed.
    pub boot: bool,
}

/// One Linux id: the class server `class` answers to `pattern`, because the
/// leaf driver `module` lists it in its `MODULE_DEVICE_TABLE`.
#[derive(Clone, Copy, Debug)]
pub struct LinuxEntry {
    pub pattern: Pattern<'static>,
    pub class: &'static str,
    pub module: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/hwbus_native.rs"));
include!(concat!(env!("OUT_DIR"), "/hwbus_linux.rs"));

/// The first pair of entries `(native index, linux index)` whose patterns
/// overlap: the check `build.rs` runs, over any two tables.
pub fn first_conflict(native: &[NativeEntry], linux: &[LinuxEntry]) -> Option<(usize, usize)> {
    crate::pattern::first_overlap(native, linux, |n| n.pattern, |l| l.pattern)
}
